    title: "परमहंस बाबाजी और भक्तिसिद्धांत सरस्वती ठाकुर के आध्यात्मिक गुरु",
    sampradaya: "ब्रह्म-माध्व-गौड़ीय",
    years: "1830 का दशक – 17 नवंबर 1915 (उत्थान एकादशी)",
    appearance: { date: "1830 का दशक", place: "वाग्यान, फ़रीदपुर, पूर्वी बंगाल" },
    disappearance: { date: "17 नवंबर 1915 (उत्थान एकादशी)", place: "कुलिया, नवद्वीप" },
    summary: "वैराग्य के साकार रूप, वे निरक्षर परमहंस जिन्होंने भक्तिसिद्धांत सरस्वती ठाकुर को दीक्षा दी और अपने निर्भय उदाहरण से पाखंड के विरुद्ध शिक्षा दी।",
    biography: [
      { p: "वैराग्य के साकार रूप श्रील गौर किशोर दास बाबाजी महाराज का आविर्भाव 1830 के दशक में पूर्वी बंगाल के फ़रीदपुर ज़िले के वाग्यान में हुआ। बीस वर्ष से अधिक समय तक वे अनाज के दलाल और गृहस्थ रहे। पत्नी के देहांत के बाद उन्होंने वृंदावन में भागवत दास बाबाजी से बाबाजी दीक्षा ली और लगभग तीस वर्ष व्रज में भ्रमण किया। 1897 से वे नवद्वीप में रहे, सूखा अनाज भिक्षा में माँगते, फेंके हुए वस्त्र पहनते और हर सुख-सुविधा को ठुकराते। भौतिक उद्देश्यों से आने वाले लोगों को दूर रखने के लिए वे एक बार एक शौचालय में भी रहे। अपने अंतिम वर्षों में दृष्टिहीन होते हुए भी उन्होंने निर्भय होकर पाखंड को उजागर किया और भक्तिविनोद ठाकुर को अपना शिक्षा गुरु माना। उनके एकमात्र दीक्षित शिष्य श्रील भक्तिसिद्धांत सरस्वती ठाकुर थे। जब वे 16 नवंबर 1915 को कुलिया में विदा हुए, तो भक्तिसिद्धांत सरस्वती ने उन प्रतिद्वंद्वी बाबाजियों का सामना किया जो लाभ के लिए उनका शरीर चाहते थे, और स्वयं उन्हें समाधि दी।" },
      { p: "वे एकादशी पर जल तक त्यागकर पूर्ण उपवास करते थे, और कहते थे कि जो भोजन (स्वादिष्ट खाना) चाहता है वह अपना भजन बिगाड़ लेता है। वे नियमित रूप से स्वानंद-सुखद-कुंज में भक्तिविनोद ठाकुर की भागवत कक्षाएँ सुनने आते थे। जब भक्तिसिद्धांत सरस्वती ने दीक्षा माँगी, तो उन्होंने उन्हें स्वीकार करने से पहले तीन बार उनकी परीक्षा ली। एक बार बाबाजी वेश में पाखंडियों से लज्जित होकर उन्होंने बढ़िया धोती और शॉल पहन ली, यह कहते हुए कि लंगोटी पहनकर अनैतिक जीवन जीने से सज्जन की तरह वस्त्र पहनना अच्छा है। उन्होंने एक सेवक को त्याग दिया जो चुपके से उनको मिला दान अपने ससुर को भेज देता था।" },
    ],
    teachings: [
      { p: "एकांत भजन का अनुकरण करने के बजाय भक्तों के संग में पवित्र नाम का जप करें; भाव छिपाना चाहिए, दिखाना नहीं; और साधु के कठोर वचन माया को भगाने की औषधि हैं।" },
    ],
    qualities: [
      { p: "वैराग्य, निर्भयता, पाखंड से घृणा, विनम्रता, भौतिक सहारे से स्वतंत्रता" },
    ],
